-- GIRO: schema MySQL 8+, rerunnable and compatible with the JSON runtime.
CREATE DATABASE IF NOT EXISTS giro CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE giro;

CREATE TABLE IF NOT EXISTS workshops (
  id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(254), phone VARCHAR(30), address VARCHAR(255), city VARCHAR(120), state CHAR(2), focus VARCHAR(100), settings JSON, metadata JSON,
  notifications_enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS workshop_settings (workshop_id CHAR(36) PRIMARY KEY, settings JSON NOT NULL, updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY (workshop_id) REFERENCES workshops(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users (
  id CHAR(36) PRIMARY KEY, workshop_id CHAR(36), name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL, password_hash VARCHAR(255) NOT NULL, phone VARCHAR(30), role VARCHAR(30) NOT NULL DEFAULT 'OWNER', status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', active BOOLEAN NOT NULL DEFAULT TRUE, specialty VARCHAR(120), state CHAR(2), city VARCHAR(120), address VARCHAR(255), password_updated_at DATETIME(3), activated_at DATETIME(3), last_login_at DATETIME(3), metadata JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), UNIQUE KEY uq_users_email (email), KEY ix_users_workshop (workshop_id), FOREIGN KEY (workshop_id) REFERENCES workshops(id) ON DELETE SET NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions (id CHAR(64) PRIMARY KEY, user_id CHAR(36) NOT NULL, expires_at DATETIME(3) NOT NULL, last_seen_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), KEY (user_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_reset_tokens (id CHAR(36) PRIMARY KEY, user_id CHAR(36), token_hash CHAR(64) NOT NULL, expires_at DATETIME(3) NOT NULL, used_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY (token_hash), KEY (user_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS invitation_tokens (id CHAR(36) PRIMARY KEY, user_id CHAR(36), workshop_id CHAR(36), token_hash CHAR(64) NOT NULL, expires_at DATETIME(3) NOT NULL, used_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY (token_hash), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (workshop_id) REFERENCES workshops(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS leads (id VARCHAR(64) PRIMARY KEY, name VARCHAR(120) NOT NULL, workshop_name VARCHAR(120) NOT NULL, whatsapp VARCHAR(30) NOT NULL, email VARCHAR(254) NOT NULL, state CHAR(2) NOT NULL, state_name VARCHAR(80), city VARCHAR(120) NOT NULL, workshop_size VARCHAR(40), plan VARCHAR(40), message TEXT, source VARCHAR(60) NOT NULL DEFAULT 'landing', status VARCHAR(30) NOT NULL DEFAULT 'new', contacted_at DATETIME(3), converted_at DATETIME(3), metadata JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), KEY (status, created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS clients (id CHAR(36) PRIMARY KEY, workshop_id CHAR(36) NOT NULL, name VARCHAR(120) NOT NULL, phone VARCHAR(30) NOT NULL DEFAULT '', email VARCHAR(254), notes TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, metadata JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), KEY (workshop_id, name), FOREIGN KEY (workshop_id) REFERENCES workshops(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vehicles (id CHAR(36) PRIMARY KEY, workshop_id CHAR(36) NOT NULL, client_id CHAR(36) NOT NULL, brand VARCHAR(60) NOT NULL, model VARCHAR(120) NOT NULL, year SMALLINT UNSIGNED, plate VARCHAR(10) NOT NULL DEFAULT '', mileage INT UNSIGNED NOT NULL DEFAULT 0, next_service VARCHAR(255), active BOOLEAN NOT NULL DEFAULT TRUE, metadata JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), UNIQUE KEY (workshop_id, plate), FOREIGN KEY (workshop_id) REFERENCES workshops(id) ON DELETE CASCADE, FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS service_templates (
  id CHAR(36) PRIMARY KEY, workshop_id CHAR(36) NOT NULL, name VARCHAR(160) NOT NULL, default_price DECIMAL(12,2) NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  UNIQUE KEY uq_service_template_workshop_name (workshop_id,name), KEY ix_service_templates_workshop_active (workshop_id,active), FOREIGN KEY (workshop_id) REFERENCES workshops(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS service_orders (
  id BIGINT UNSIGNED PRIMARY KEY, workshop_id CHAR(36) NOT NULL, client_id CHAR(36), vehicle_id CHAR(36), assigned_user_id CHAR(36), created_by CHAR(36), closed_by CHAR(36), client_name VARCHAR(120), client_phone VARCHAR(30), vehicle_brand VARCHAR(60), vehicle_model VARCHAR(120), plate VARCHAR(10), year SMALLINT UNSIGNED, mileage INT UNSIGNED, service VARCHAR(160), issue TEXT, diagnosis TEXT, status TINYINT UNSIGNED NOT NULL DEFAULT 0, status_before_close TINYINT UNSIGNED, cancelled_at DATETIME(3), priority VARCHAR(30) NOT NULL DEFAULT 'Normal', estimated_value DECIMAL(12,2) DEFAULT 0, discount DECIMAL(12,2) DEFAULT 0, labor_items JSON, pending_items JSON, creation_operation_id VARCHAR(200), creation_operation_hash CHAR(64), entry_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), due_at DATETIME(3), started_at DATETIME(3), finished_at DATETIME(3), closed_at DATETIME(3), paused BOOLEAN NOT NULL DEFAULT FALSE, late BOOLEAN NOT NULL DEFAULT FALSE, incomplete BOOLEAN NOT NULL DEFAULT FALSE, metadata JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), KEY (workshop_id,status), KEY (assigned_user_id), UNIQUE KEY uq_order_operation (workshop_id,created_by,creation_operation_id), FOREIGN KEY (workshop_id) REFERENCES workshops(id) ON DELETE CASCADE, FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE SET NULL, FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE SET NULL, FOREIGN KEY (assigned_user_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY (closed_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, user_id CHAR(36), old_status TINYINT UNSIGNED, new_status TINYINT UNSIGNED NOT NULL, action VARCHAR(80), note VARCHAR(500), metadata JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uq_order_history_event (order_id,created_at,action), KEY (order_id,created_at), FOREIGN KEY (order_id) REFERENCES service_orders(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_notes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, user_id CHAR(36), note_type VARCHAR(30) NOT NULL DEFAULT 'observation', content TEXT NOT NULL, metadata JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY (order_id) REFERENCES service_orders(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, value DECIMAL(12,2) NOT NULL DEFAULT 0, metadata JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY (order_id) REFERENCES service_orders(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_parts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, source_id CHAR(36), order_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, quantity DECIMAL(12,3) NOT NULL DEFAULT 1, unit_value DECIMAL(12,2) NOT NULL DEFAULT 0, metadata JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uq_order_part_source (source_id), FOREIGN KEY (order_id) REFERENCES service_orders(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_items (id CHAR(36) PRIMARY KEY, workshop_id CHAR(36) NOT NULL, name VARCHAR(120) NOT NULL, sku VARCHAR(80), category VARCHAR(80), unit VARCHAR(20) NOT NULL, tracked BOOLEAN NOT NULL DEFAULT TRUE, quantity DECIMAL(18,3) NOT NULL DEFAULT 0, minimum_quantity DECIMAL(18,3) NOT NULL DEFAULT 0, cost_price DECIMAL(12,2), active BOOLEAN NOT NULL DEFAULT TRUE, metadata JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), KEY (workshop_id,active), FOREIGN KEY (workshop_id) REFERENCES workshops(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_operations (id VARCHAR(200) PRIMARY KEY, workshop_id CHAR(36) NOT NULL, actor_id CHAR(36), operation_type VARCHAR(40), payload_hash CHAR(64), metadata JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY (workshop_id,id), FOREIGN KEY (workshop_id) REFERENCES workshops(id) ON DELETE CASCADE, FOREIGN KEY (actor_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_movements (id CHAR(36) PRIMARY KEY, workshop_id CHAR(36) NOT NULL, item_id CHAR(36), order_id BIGINT UNSIGNED, user_id CHAR(36), type VARCHAR(20) NOT NULL, quantity DECIMAL(18,3) NOT NULL, balance_after DECIMAL(18,3), reason VARCHAR(1000), metadata JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), KEY (workshop_id,created_at), FOREIGN KEY (workshop_id) REFERENCES workshops(id) ON DELETE CASCADE, FOREIGN KEY (item_id) REFERENCES inventory_items(id) ON DELETE SET NULL, FOREIGN KEY (order_id) REFERENCES service_orders(id) ON DELETE SET NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_reservations (id CHAR(36) PRIMARY KEY, workshop_id CHAR(36) NOT NULL, item_id CHAR(36), order_id BIGINT UNSIGNED NOT NULL, quantity DECIMAL(18,3) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', metadata JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), KEY (order_id,status), FOREIGN KEY (workshop_id) REFERENCES workshops(id) ON DELETE CASCADE, FOREIGN KEY (item_id) REFERENCES inventory_items(id) ON DELETE SET NULL, FOREIGN KEY (order_id) REFERENCES service_orders(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activity_logs (id CHAR(36) PRIMARY KEY, workshop_id CHAR(36), user_id CHAR(36), entity_type VARCHAR(60) NOT NULL, entity_id VARCHAR(64) NOT NULL, action VARCHAR(80) NOT NULL, details JSON, metadata JSON, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), KEY (workshop_id,created_at), KEY (entity_type,entity_id), FOREIGN KEY (workshop_id) REFERENCES workshops(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
